// Character-specific quote overrides — keyed by AVATARS array index.
// To assign a character their own lines, find their index (0-based, matches
// the order of ALL_NUMS in build.py, currently:
//   0: avatar_7    1: avatar_9 (pickle)   2: avatar_10   3: avatar_12
//   4: avatar_13   5: avatar_14           6: avatar_15   7: avatar_16
//   8: avatar_17   9: avatar_18          10: avatar_19  11: avatar_20
//  12: avatar_21  13: avatar_22          14: avatar_23  15: avatar_24
//  16: avatar_25  17: avatar_26          18: avatar_27  19: avatar_30
//  20: avatar_31  21: avatar_32          22: avatar_33  23: avatar_34
//  24: avatar_35
// ) and add an entry below.
const QUOTES_BY_AVATAR = {
  // The pickle character (avatar 9 / index 1)
  1: [
    "Don't get yourself in a pickle.",
    "I'm kind of a big dill.",
    "Brine and shine.",
    "I relish this opportunity.",
    "Pickle me impressed.",
  ],
  // Add more characters here, e.g.:
  // 0: ["Quote 1", "Quote 2"],   // for AVATARS[0] (avatar 7)
};

function getQuoteFor(avatarIdx) {
  const specific = QUOTES_BY_AVATAR[avatarIdx];
  if (specific && specific.length) {
    return specific[Math.floor(Math.random() * specific.length)];
  }
  return QUOTES_GENERIC[Math.floor(Math.random() * QUOTES_GENERIC.length)];
}

function pickRandom(n, poolSize) {
  // Pick `n` unique indices in [0, poolSize) — Fisher-Yates partial shuffle.
  const arr = Array.from({ length: poolSize }, (_, i) => i);
  for (let i = arr.length - 1; i > arr.length - 1 - n; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr.slice(arr.length - n);
}

// ─── Scoring ──────────────────────────────────────────────────────────────
// CLASSIC: lower is better. Moves weighted heavier than seconds.
function computeScoreClassic(moves, time) {
  return moves * 10 + time;
}
// SPEED: higher is better. matches × 100 + bonus seconds for finishing under time.
function computeScoreSpeed(matches, timeRemaining, allMatched) {
  return matches * 100 + (allMatched ? timeRemaining : 0);
}
// PICKLE: lower is better. moves + time + heavy pepper penalty.
function computeScorePickle(moves, time, peppers) {
  return moves * 10 + time + peppers * 30;
}
// BOSS: higher is better. cards cleared × 25 + clear bonus + time bonus if all cleared.
function computeScoreBoss(cardsCleared, timeRemaining, allMatched) {
  return cardsCleared * 25 + (allMatched ? 200 + timeRemaining * 5 : 0);
}

// ─── Leaderboard storage (window.storage, mode-keyed) ─────────────────────
const LB_KEY_PREFIX = 'memory-mash:leaderboard';
const LB_MAX = 10;
function lbKey(mode) { return `${LB_KEY_PREFIX}:${mode}`; }

async function loadLeaderboard(mode) {
  try {
    if (typeof window === 'undefined' || !window.storage) return [];
    const result = await window.storage.get(lbKey(mode));
    if (!result) return [];
    const data = JSON.parse(result.value);
    return Array.isArray(data) ? data : [];
  } catch {
    return [];
  }
}

async function saveLeaderboard(mode, entries) {
  try {
    if (typeof window === 'undefined' || !window.storage) return false;
    await window.storage.set(lbKey(mode), JSON.stringify(entries));
    return true;
  } catch (err) {
    console.error('Leaderboard save failed:', err);
    return false;
  }
}

// Mode-aware insertion: classic/pickle ranks ascending (lower better),
// speed/boss ranks descending (higher better).
function insertEntry(entries, entry, mode) {
  const higherBetter = mode === 'speed' || mode === 'boss';
  const cmp = higherBetter
    ? (a, b) => b.score - a.score
    : (a, b) => a.score - b.score;
  const next = [...entries, entry].sort(cmp).slice(0, LB_MAX);
  const rank = next.indexOf(entry) + 1;
  return { entries: next, rank: rank > 0 ? rank : null };
}

function makeDeck(mode) {
  const rid = () => Math.random().toString(36).slice(2, 7);

  if (mode === 'pickle') {
    // 6 avatar pairs (12 cards) + 2 pickles + 2 peppers = 16 cards.
    // Avatar 9 is the pickle character — exclude it from the regular pool.
    // (Index 1 in the AVATARS array, which corresponds to avatar number 9.)
    const PICKLE_AVATAR_IDX = 1;
    const PICKLE_PAIRS = 6;
    const pool = AVATARS.map((_, i) => i).filter(i => i !== PICKLE_AVATAR_IDX);
    // Pick 6 indices from the filtered pool
    const shuffled = [...pool];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    const chosen = shuffled.slice(0, PICKLE_PAIRS);
    const avatarCards = [...chosen, ...chosen].map((avatarIdx, i) => ({
      type: 'avatar',
      key: `a${i}-${rid()}`,
      avatarIdx,
      flipped: false,
      matched: false,
    }));
    const pickleCards = [0, 1].map(i => ({
      type: 'pickle',
      key: `pi${i}-${rid()}`,
      flipped: false,
      matched: false,
    }));
    // Pick ONE pepper variant for this whole game so both peppers match each other
    // visually (looks intentional, not random per-card).
    const pepperVariant = Math.floor(Math.random() * PEPPERS.length);
    const pepperCards = [0, 1].map(i => ({
      type: 'pepper',
      key: `pe${i}-${rid()}`,
      pepperVariant,
      flipped: false,
      matched: false,
    }));
    const deck = [...avatarCards, ...pickleCards, ...pepperCards];
    for (let i = deck.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [deck[i], deck[j]] = [deck[j], deck[i]];
    }
    return deck;
  }

  if (mode === 'boss') {
    // 6 avatar pairs (12 cards) + 4 Boss cards (all same character) = 16 cards.
    // Pick a random avatar to be the Boss; exclude it from the regular pool
    // so the same character can't appear as both Boss and pair.
    const bossAvatarIdx = Math.floor(Math.random() * AVATARS.length);
    const BOSS_PAIRS = 6;
    const pool = AVATARS.map((_, i) => i).filter(i => i !== bossAvatarIdx);
    const shuffled = [...pool];
    for (let i = shuffled.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }
    const chosen = shuffled.slice(0, BOSS_PAIRS);
    const avatarCards = [...chosen, ...chosen].map((avatarIdx, i) => ({
      type: 'avatar',
      key: `a${i}-${rid()}`,
      avatarIdx,
      flipped: false,
      matched: false,
    }));
    const bossCards = [0, 1, 2, 3].map(i => ({
      type: 'boss',
      key: `b${i}-${rid()}`,
      avatarIdx: bossAvatarIdx, // for rendering
      flipped: false,
      matched: false,
    }));
    const deck = [...avatarCards, ...bossCards];
    for (let i = deck.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [deck[i], deck[j]] = [deck[j], deck[i]];
    }
    return deck;
  }

  // Default (classic / speed): 8 avatar pairs
  const chosen = pickRandom(NUM_PAIRS, AVATARS.length);
  const deck = [...chosen, ...chosen].map((avatarIdx, idx) => ({
    type: 'avatar',
    key: `${idx}-${rid()}`,
    avatarIdx,
    flipped: false,
    matched: false,
  }));
  for (let i = deck.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [deck[i], deck[j]] = [deck[j], deck[i]];
  }
  return deck;
}

function fmtTime(secs) {
  const m = Math.floor(secs / 60);
  const s = secs % 60;
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

